insert into public.asci_profilleri (profil_id, tanitim, uzmanliklar, semtler, baslangic_fiyati, musait_gunler, onayli_mi, guncelleme_tarihi) values
('dddddddd-0000-4000-8000-000000000001'::uuid, 'Ege mutfağının zeytinyağlılarını ve mevsim yemeklerini evinizde taze taze hazırlıyorum. On iki yıllık deneyimim var.', array['Ege', 'Türk mutfağı', 'Diyet']::text[], array['Kadıköy', 'Moda', 'Ataşehir']::text[], 5200, array['Pazartesi', 'Salı', 'Çarşamba']::text[], true, now() - interval '1 days'),
('dddddddd-0000-4000-8000-000000000002'::uuid, 'Gaziantepliyim; kebabın, köftenin ve baklavanın en doğrusunu biliyorum. Haftalık menüler hazırlarım.', array['Antep', 'Türk mutfağı']::text[], array['Şişli', 'Beşiktaş', 'Levent']::text[], 6500, array['Perşembe', 'Cuma', 'Cumartesi']::text[], true, now() - interval '2 days'),
('dddddddd-0000-4000-8000-000000000003'::uuid, 'Beslenme danışmanlığı geçmişimle vegan ve düşük kalorili, doyurucu menüler hazırlıyorum.', array['Vegan', 'Diyet']::text[], array['Üsküdar', 'Kadıköy']::text[], 4800, array['Pazartesi', 'Çarşamba', 'Cuma']::text[], true, now() - interval '3 days'),
('dddddddd-0000-4000-8000-000000000004'::uuid, 'Çocukların sevdiği, besleyici ve renkli yemekler. Alerji ve seçici yeme konusunda deneyimliyim.', array['Çocuk yemekleri', 'Tatlı ve pasta']::text[], array['Bakırköy', 'Yeşilköy']::text[], 4500, array['Salı', 'Perşembe']::text[], true, now() - interval '4 days'),
('dddddddd-0000-4000-8000-000000000005'::uuid, 'Karadeniz kökenli bir ailede büyüdüm. Balık ve deniz ürünlerini taptaze, en sade ve lezzetli haliyle pişiririm.', array['Deniz ürünleri', 'Karadeniz']::text[], array['Sarıyer', 'Beşiktaş', 'Bebek']::text[], 7000, array['Çarşamba', 'Cuma', 'Pazar']::text[], true, now() - interval '5 days'),
('dddddddd-0000-4000-8000-000000000006'::uuid, 'Anne eli değmiş gibi ev yemekleri: kuru fasulye, pilav, sarma ve sütlaç. Evinizde yemek kokusu eksik olmasın.', array['Türk mutfağı']::text[], array['Kadıköy', 'Maltepe', 'Kartal']::text[], 4200, array['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe']::text[], true, now() - interval '6 days'),
('dddddddd-0000-4000-8000-000000000007'::uuid, 'Trabzonluyum; mısır ekmeği, hamsi ve çorba benim işim. Doyurucu ve geleneksel menüler.', array['Karadeniz', 'Türk mutfağı']::text[], array['Beyoğlu', 'Şişli', 'Kâğıthane']::text[], 5000, array['Pazartesi', 'Cuma', 'Cumartesi']::text[], true, now() - interval '7 days'),
('dddddddd-0000-4000-8000-000000000008'::uuid, 'Pastacılık eğitimi aldım. Ev yemeklerinin yanına tatlı ve börek ikramı eklemekten keyif alırım.', array['Tatlı ve pasta']::text[], array['Nişantaşı', 'Etiler', 'Beşiktaş']::text[], 5500, array['Cumartesi', 'Pazar']::text[], true, now() - interval '8 days'),
('dddddddd-0000-4000-8000-000000000009'::uuid, 'Izgaranın ve kebabın ustasıyım; salata ve mezelerle tam bir sofra kurarım.', array['Antep', 'Türk mutfağı']::text[], array['Ataşehir', 'Üsküdar', 'Ümraniye']::text[], 6000, array['Salı', 'Perşembe', 'Cumartesi']::text[], true, now() - interval '9 days'),
('dddddddd-0000-4000-8000-000000000010'::uuid, 'Diyetisyenlerle çalışan bir aşçıyım. Porsiyon ve kalori hedefinize uygun, lezzetli menüler hazırlarım.', array['Diyet', 'Vegan']::text[], array['Kadıköy', 'Moda', 'Fenerbahçe']::text[], 5300, array['Pazartesi', 'Çarşamba', 'Perşembe']::text[], true, now() - interval '10 days'),
('dddddddd-0000-4000-8000-000000000011'::uuid, 'Klasik Türk mutfağı: köfte, pilav, kuru fasulye ve taze salata. Sade ve bol yemek.', array['Türk mutfağı']::text[], array['Bakırköy', 'Zeytinburnu', 'Fatih']::text[], 4000, array['Salı', 'Çarşamba', 'Cuma']::text[], true, now() - interval '11 days'),
('dddddddd-0000-4000-8000-000000000012'::uuid, 'İzmirliyim; otlu, zeytinyağlı ve deniz kokulu Ege sofralarını İstanbul evlerine getiriyorum.', array['Ege', 'Türk mutfağı']::text[], array['Beşiktaş', 'Ortaköy', 'Sarıyer']::text[], 5800, array['Pazartesi', 'Perşembe', 'Cuma']::text[], true, now() - interval '12 days'),
('dddddddd-0000-4000-8000-000000000013'::uuid, 'Balıkçı ailesinden geliyorum. Taze balık, kalamar ve karides; sunumu da şık.', array['Deniz ürünleri']::text[], array['Kadıköy', 'Caddebostan', 'Bostancı']::text[], 6800, array['Çarşamba', 'Cuma']::text[], true, now() - interval '13 days'),
('dddddddd-0000-4000-8000-000000000014'::uuid, 'İki çocuk annesiyim; çocuklar için sağlıklı, eğlenceli ve alerjene dikkat eden yemekler hazırlıyorum.', array['Çocuk yemekleri']::text[], array['Ataşehir', 'Kozyatağı', 'Kadıköy']::text[], 4600, array['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe']::text[], true, now() - interval '14 days'),
('dddddddd-0000-4000-8000-000000000015'::uuid, 'Rizeli bir aşçıyım. Sıcak çorbalar, fasulye ve mısır unlu lezzetlerle sofranızı ısıtırım.', array['Karadeniz', 'Türk mutfağı']::text[], array['Üsküdar', 'Çengelköy', 'Beykoz']::text[], 4900, array['Cuma', 'Cumartesi', 'Pazar']::text[], true, now() - interval '15 days'),
('dddddddd-0000-4000-8000-000000000016'::uuid, 'Bitkisel mutfakta Türk lezzetlerini yeniden yorumluyorum; et ve süt ürünü kullanmadan doyurucu yemekler.', array['Vegan']::text[], array['Beyoğlu', 'Cihangir', 'Şişli']::text[], 5400, array['Pazartesi', 'Salı', 'Cuma']::text[], true, now() - interval '16 days'),
('dddddddd-0000-4000-8000-000000000017'::uuid, 'Antep usulü yemekler: yuvalama, kebap, mantı ve fıstıklı baklava. Büyük sofralar için ideal.', array['Antep']::text[], array['Esenyurt', 'Başakşehir', 'Bakırköy']::text[], 5600, array['Perşembe', 'Cuma', 'Cumartesi']::text[], true, now() - interval '17 days'),
('dddddddd-0000-4000-8000-000000000018'::uuid, 'Hafif ama doyurucu ev yemekleri. Haftalık plan yapar, alışverişi listeye göre ben tamamlarım.', array['Türk mutfağı', 'Diyet']::text[], array['Kadıköy', 'Göztepe', 'Acıbadem']::text[], 5100, array['Salı', 'Çarşamba', 'Perşembe']::text[], true, now() - interval '18 days'),
